from typing import List, Tuple, Set


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    # Preprocess tiles to include both orientations and remove duplicates
    unique_tiles = set()
    for a, b in tiles:
        if a <= h and b <= w or a <= w and b <= h:
            unique_tiles.add((min(a, b), max(a, b)))
    unique_tiles = list(unique_tiles)

    # If no tiles can fit in the grid, return False
    if not unique_tiles:
        return False

    # We'll use backtracking to try to cover the grid
    # The grid will be represented as a list of lists, with 0 meaning uncovered
    grid = [[0] * w for _ in range(h)]

    # Sort tiles by size in descending order to try larger tiles first (heuristic)
    unique_tiles.sort(key=lambda x: x[0] * x[1], reverse=True)

    def backtrack():
        # Find the first uncovered cell
        for i in range(h):
            for j in range(w):
                if grid[i][j] == 0:
                    # Try to place each possible tile here
                    for tile in unique_tiles:
                        a, b = tile
                        # Try both orientations
                        for da, db in [(a, b), (b, a)]:
                            # Check if this tile fits starting at (i, j)
                            if i + da <= h and j + db <= w:
                                # Check if the area is completely uncovered
                                can_place = True
                                for x in range(i, i + da):
                                    for y in range(j, j + db):
                                        if grid[x][y] != 0:
                                            can_place = False
                                            break
                                    if not can_place:
                                        break

                                if can_place:
                                    # Place the tile
                                    for x in range(i, i + da):
                                        for y in range(j, j + db):
                                            grid[x][y] = 1

                                    # Recurse
                                    if backtrack():
                                        return True

                                    # Remove the tile (backtrack)
                                    for x in range(i, i + da):
                                        for y in range(j, j + db):
                                            grid[x][y] = 0
                    # If no tile could be placed at this position, return False
                    return False
        # If we've covered the entire grid, return True
        return True

    return backtrack()
